import React, { useState, useEffect, forwardRef } from 'react';
import DatePicker from 'react-datepicker';
import { differenceInDays, startOfDay, endOfDay, addDays, isAfter, format } from 'date-fns';
import 'react-datepicker/dist/react-datepicker.css';
import CustomAlert from '../utils/CustomAlert';

const DateSelector = ({
  onDateChange,
  pickerMinWidth = '60px',
  pickerHeight = '22px',
  fontSize = '11px',
  islabel = false,
  initialFromDiff = -7,
  initialToDiff = 0,
  /**
   * [추가] returnType 설정
   * 'diff': 기존 방식 (-7, 0)
   * 'date': 날짜만 (2026-01-31)
   * 'datetime': 시분초 포함 (2026-01-31 00:00:00 / 23:59:59)
   */
  returnType = 'diff',
}) => {
  const [fromDate, setFromDate] = useState(() => addDays(startOfDay(new Date()), initialFromDiff));
  const [toDate, setToDate] = useState(() => addDays(startOfDay(new Date()), initialToDiff));
  const [dateAlert, setDateAlert] = useState({ isOpen: false, message: '' });

  // [수정] 날짜 데이터를 타입에 맞춰 변환하는 핵심 로직
  const getFormattedData = (fDate, tDate) => {
    const today = startOfDay(new Date());

    switch (returnType) {
      case 'date':
        return {
          from: format(fDate, 'yyyy-MM-dd'),
          to: format(tDate, 'yyyy-MM-dd'),
        };
      case 'datetime':
        return {
          from: format(startOfDay(fDate), 'yyyy-MM-dd HH:mm:ss'),
          to: format(endOfDay(tDate), 'yyyy-MM-dd HH:mm:ss'),
        };
      case 'diff':
      default:
        return {
          from: differenceInDays(startOfDay(fDate), today),
          to: differenceInDays(startOfDay(tDate), today),
        };
    }
  };

  // 초기 마운트 시 부모에게 전달
  useEffect(() => {
    onDateChange(getFormattedData(fromDate, toDate));
  }, []);

  const handleFromChange = (date) => {
    if (isAfter(startOfDay(date), startOfDay(toDate))) {
      setDateAlert({ isOpen: true, message: '시작일이 종료일보다 늦을 수 없습니다.' });
      return;
    }
    setFromDate(date);
    onDateChange(getFormattedData(date, toDate));
  };

  const handleToChange = (date) => {
    const today = startOfDay(new Date());
    const selectedDate = startOfDay(date);

    if (isAfter(selectedDate, today)) {
      setDateAlert({ isOpen: true, message: '종료일은 오늘 이후 날짜를 선택할 수 없습니다.' });
      return;
    }
    if (isAfter(startOfDay(fromDate), selectedDate)) {
      setDateAlert({ isOpen: true, message: '종료일은 시작일보다 빠를 수 없습니다.' });
      return;
    }
    setToDate(date);
    onDateChange(getFormattedData(fromDate, date));
  };

  // ... (기본 calculateDiff, getDDayString, CustomInput 코드는 기존과 동일) ...
  const calculateDiff = (targetDate) => {
    if (!targetDate) return 0;
    const today = startOfDay(new Date());
    const target = startOfDay(targetDate);
    return differenceInDays(target, today);
  };

  const getDDayString = (val) => {
    const diff = typeof val === 'object' ? calculateDiff(val) : val;
    return diff > 0 ? `+${diff}` : `${diff}`;
  };

  const CustomInput = forwardRef(({ value, onClick }, ref) => (
    <button
      onClick={onClick}
      ref={ref}
      style={{ ...buttonStyle, height: pickerHeight, minWidth: pickerMinWidth, fontSize }}
    >
      <span style={{ color: '#3182ce' }}>D</span> {getDDayString(new Date(value))}
      <span style={arrowStyle}>▾</span>
    </button>
  ));

  return (
    <div style={containerStyle}>
      <div style={pickerWrapper}>
        {islabel && <span style={{ ...labelStyle, fontSize }}>From</span>}
        <DatePicker
          selected={fromDate}
          onChange={handleFromChange}
          customInput={<CustomInput />}
          dateFormat="yyyy-MM-dd"
        />
      </div>
      <span style={separatorStyle}>~</span>
      <div style={pickerWrapper}>
        {islabel && <span style={{ ...labelStyle, fontSize }}>To</span>}
        <DatePicker
          selected={toDate}
          onChange={handleToChange}
          customInput={<CustomInput />}
          dateFormat="yyyy-MM-dd"
        />
      </div>

      {dateAlert.isOpen && (
        <CustomAlert
          title="날짜 선택 오류"
          message={dateAlert.message}
          onConfirm={() => setDateAlert({ ...dateAlert, isOpen: false })}
        />
      )}
    </div>
  );
};

// ... 스타일 정의 동일 ...
const containerStyle = { display: 'flex', alignItems: 'center', gap: '4px' };
const pickerWrapper = { display: 'flex', alignItems: 'center', gap: '4px' };
const labelStyle = { color: '#718096', fontWeight: '600' };
const separatorStyle = { color: '#cbd5e0', fontSize: '11px' };
const arrowStyle = { fontSize: '8px', marginLeft: '4px', opacity: 0.6 };
const buttonStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  padding: '0 8px',
  border: '1px solid #e2e8f0',
  borderRadius: '4px',
  backgroundColor: '#fff',
  cursor: 'pointer',
  fontWeight: '800',
  color: '#2d3748',
  transition: 'all 0.2s',
  boxShadow: 'inset 0 1px 2px rgba(0,0,0,0.02)',
};

export default DateSelector;
