export const generateCondition = (category, keyword = '', maxCount = 1) => {
  const baseData = {
    line: ['Line-A', 'Line-B', 'Line-C', 'Line-D'],
    process: ['Photo', 'Etch', 'Clean', 'Diff', 'CMP', 'Ion-Imp'],
    partid: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    product: ['DRAM-8G', 'NAND-128G', 'CPU-X1', 'GPU-V2', 'MCU-S3'],
    equip: ['EQP-01', 'EQP-02', 'EQP-03', 'EQP-04', 'EQP-05'],
    lottype: ['Production', 'Test', 'Engineer', 'Rework'],
    step: ['HS010092', 'HS010093', 'HS010094', 'HS010095'],
    lot: ['LOTID-001', 'LOTID-002', 'LOTID-003', 'LOTID-004', 'LOTID-005'],
    wafer: ['W01', 'W02', 'W03', 'W04', 'W05', 'W06', 'W07', 'W08', 'W09', 'W10'],
    item: [
      'Thickness',
      'Critical Dimension',
      'Overlay',
      'Defect Count',
      'Temperature',
      'Pressure',
      'Flow Rate',
      'Humidity',
    ],
  };

  let list = [];
  let source = baseData[category] || [];

  // y1item, y2item 대응
  if (category === 'y1item' || category === 'y2item') {
    source = baseData['item'];
  }

  // --- 1. 데이터 생성 로직 ---
  if (category === 'lot') {
    // lot인 경우: 모든 lot과 모든 wafer를 조합 (ex: LOTID-001_W01)
    baseData.lot.forEach((l) => {
      baseData.wafer.forEach((w) => {
        list.push(`${l}_${w}`);
      });
    });
  } else {
    // 일반 카테고리: baseData의 source만큼 생성
    source.forEach((val) => {
      if ((category === 'step' || category === 'y1item' || category === 'y2item') && maxCount > 1) {
        list.push({
          [category]: val,
          desc: `test용 ${category}`,
        });
      } else {
        list.push(val);
      }
    });
  }

  // --- 2. 필터링 로직 ---
  if (keyword && keyword.length > 0) {
    list = list.filter((item) => {
      // 객체인 경우(step 등)와 문자열인 경우 분기 처리
      const targetValue = typeof item === 'object' ? String(item[category]) : String(item);

      // keyword 배열 중 하나라도 포함되어 있는지 확인
      return keyword.some((k) => targetValue.toLowerCase().includes(k.toLowerCase()));
    });
  }

  return list;
};
