// DieGenerator.js

// Wafer Die Data Generator for Cartesian coordinates
export const generateDies = (params, keys, seriesCount = 1) => {
  let dieList = [];
  let dataList = [];
  let min = 1000000;
  let max = -1000000;

  const validRadian = (params.waferSize - 2.0 * params.waferEdge) / 2.0; // Wafer radius in data units
  const diexLen =
    (params.waferSize - 2.0 * params.waferEdge) / (params.dieSizeX + params.scribeSize);
  const diexDum =
    (params.waferSize - 2.0 * params.waferEdge) % (params.dieSizeX + params.scribeSize);
  const dieyLen =
    (params.waferSize - 2.0 * params.waferEdge) / (params.dieSizeY + params.scribeSize);
  const dieyDum =
    (params.waferSize - 2.0 * params.waferEdge) % (params.dieSizeY + params.scribeSize);

  for (let ix = 0; ix < diexLen; ix++) {
    for (let iy = 0; iy < dieyLen; iy++) {
      const xPos = -validRadian + diexDum / 2.0 + ix * (params.dieSizeX + params.scribeSize);
      const yPos = -validRadian + dieyDum / 2.0 + iy * (params.dieSizeY + params.scribeSize);
      var valid = false;
      if (xPos < 0.0 && yPos < 0.0) {
        valid = Math.sqrt(xPos ** 2 + yPos ** 2) <= validRadian;
      }

      if (xPos >= 0.0 && yPos >= 0.0) {
        valid =
          Math.sqrt((xPos + params.dieSizeX) ** 2 + (yPos + params.dieSizeY) ** 2) <= validRadian;
      }

      if (xPos < 0.0 && yPos >= 0.0) {
        valid = Math.sqrt(xPos ** 2 + (yPos + params.dieSizeY) ** 2) <= validRadian;
      }

      if (xPos >= 0 && yPos < 0) {
        valid = Math.sqrt((xPos + params.dieSizeX) ** 2 + yPos ** 2) <= validRadian;
      }

      if (valid) {
        if (params.mapType === 'EDS') {
          const binNumber =
            ix % 3 === 0 || ix % 2 === 0 || iy % 2 === 0 ? 1 : Math.floor(Math.random() * 20) + 1;
          let status = 'Good';
          if (binNumber > 3) status = 'Fail';

          dieList.push({
            id: `D${ix}-${iy}`,
            x: xPos,
            y: yPos,
            width: params.dieSizeX,
            height: params.dieSizeY,
            bin: binNumber,
            status: status,
            partid: keys.partid,
            step: keys.step,
            item: keys.item,
            lotid: keys.lotid,
            waferid: keys.waferid,
          });
        } else if (params.mapType === 'MEASURE' || params.mapType === 'MEASURE-Contour') {
          const itemValue = Math.floor(Math.random() * (100 - 60 + 1) + 60);
          min = min > itemValue ? itemValue : min;
          max = max < itemValue ? itemValue : max;
          let status = 'Good';

          if (itemValue < 75) status = 'Fail';

          dieList.push({
            id: `D${ix}-${iy}`,
            x: xPos,
            y: yPos,
            width: params.dieSizeX,
            height: params.dieSizeY,
            itemValue: itemValue,
            status: status,
            partid: keys.partid,
            step: keys.step,
            item: keys.item,
            lotid: keys.lotid,
            waferid: keys.waferid,
          });
        } else if (params.mapType === 'DEFECT') {
          dieList.push({
            id: `D${ix}-${iy}`,
            x: xPos,
            y: yPos,
            width: params.dieSizeX,
            height: params.dieSizeY,
            partid: keys.partid,
            step: keys.step,
            item: keys.item,
            lotid: keys.lotid,
            waferid: keys.waferid,
          });
        } else if (params.mapType === 'METRO-CD' || params.mapType === 'METRO-CD-Contour') {
          dieList.push({
            id: `D${ix}-${iy}`,
            x: xPos,
            y: yPos,
            width: params.dieSizeX,
            height: params.dieSizeY,
            partid: keys.partid,
            step: keys.step,
            item: keys.item,
            lotid: keys.lotid,
            waferid: keys.waferid,
          });
        }
      }
    }
  }
  if (params.mapType === 'METRO-CD' || params.mapType === 'METRO-CD-Contour') {
    ({ dataList, min, max } = generateMetroCD(
      params,
      Math.floor(Math.random() * (2000 - 1000)) + 1000,
      seriesCount,
    ));
  }
  if (params.mapType === 'DEFECT') {
    dataList = generateDefects(
      params,
      Math.floor(Math.random() * (800 - 500)) + 500,
      Math.floor(Math.random() * (4 - 1)) + 1,
      Math.floor(Math.random() * (4 - 1)) + 1,
    );
  }
  const lotid = keys.lotid;

  return { dieList, dataList, min, max, lotid };
};

// Wafer Defect Data Generator for Cartesian coordinates
export const generateDefects = (params, numRandom, numClusters, numScratches, seed = 0) => {
  const dataList = [];
  const random = (s) => {
    // Seeded random for consistent defects if needed
    if (s === 0) return Math.random();
    s = Math.sin(s) * 10000;
    return s - Math.floor(s);
  };
  let currentSeed = seed;
  let range = (params.waferSize - 2 * params.waferEdge) / 2; // Wafer radius in data units

  // Helper for generating Gaussian-like distribution
  const gaussianRandom = (center, spread) =>
    center + (random(currentSeed++) + random(currentSeed++) + random(currentSeed++) - 1.5) * spread;

  // 1. Random Defects
  for (let i = 0; i < numRandom; i++) {
    //const x = (random(currentSeed++) * 2 - 1) * range;
    //const y = (random(currentSeed++) * 2 - 1) * range;
    const min = -range;
    const max = range;
    const x = Math.floor(Math.random() * (max - min + 1)) + min;
    const y = (random(currentSeed++) * 2 - 1) * range;
    if (Math.sqrt(x * x + y * y) < range) {
      currentSeed++;
      dataList.push({
        id: `R${i}`,
        x,
        y,
        type: 'Random',
        color: '#130ffa',
        size: Math.floor(Math.random() * (5000 - 1000 + 1)) + 1000,
      }); // Yellow
    }
  }

  // 2. Cluster Defects
  for (let c = 0; c < numClusters; c++) {
    const clusterCenterX = (random(currentSeed++) * 2 - 1) * range * 0.6;
    const clusterCenterY = (random(currentSeed++) * 2 - 1) * range * 0.6;
    const clusterSpread = range * (0.02 + random(currentSeed++) * 0.03); // Randomize cluster spread

    for (let i = 0; i < 50; i++) {
      // 50 defects per cluster
      const x = gaussianRandom(clusterCenterX, clusterSpread);
      const y = gaussianRandom(clusterCenterY, clusterSpread);
      if (Math.sqrt(x * x + y * y) < range) {
        currentSeed++;
        dataList.push({
          id: `C${c}-${i}`,
          x,
          y,
          type: 'Cluster',
          color: '#be0b0b',
          size: Math.floor(Math.random() * (2500 - 800 + 1)) + 800,
        }); // Orange
      }
    }
  }

  // 3. Scratch Defects
  for (let s = 0; s < numScratches; s++) {
    const startX = (random(currentSeed++) * 2 - 1) * range * 0.7;
    const startY = (random(currentSeed++) * 2 - 1) * range * 0.7;
    const endX = (random(currentSeed++) * 2 - 1) * range * 0.7;
    const endY = (random(currentSeed++) * 2 - 1) * range * 0.7;
    const scratchLength = Math.sqrt((endX - startX) ** 2 + (endY - startY) ** 2);

    if (scratchLength > range * 0.1) {
      // Only long enough scratches
      for (let i = 0; i < 20; i++) {
        // 20 defects per scratch
        const ratio = i / 19;
        const noiseX = (random(currentSeed++) - 0.5) * (range * 0.01);
        const noiseY = (random(currentSeed++) - 0.5) * (range * 0.01);
        const x = startX + (endX - startX) * ratio + noiseX;
        const y = startY + (endY - startY) * ratio + noiseY;
        if (Math.sqrt(x * x + y * y) < range) {
          dataList.push({
            id: `S${s}-${i}`,
            x,
            y,
            type: 'Scratch',
            color: '#b130aa',
            size: 1200 + random(currentSeed++) * 1200,
          }); // Red
        }
      }
    }
  }
  return dataList;
};

// Wafer cd Data Generator for Cartesian coordinates
export const generateMetroCD = (params, cdCount, seriesCount = 1) => {
  const dataList = [];
  let min = 1000000;
  let max = -1000000;

  // 1. Wafer 유효 Range 구한다.
  let range = (params.waferSize - 2 * params.waferEdge) / 2; // Wafer radius in data units

  // 2. CD 데이터 생성
  for (let s = 0; s < seriesCount; s++) {
    for (let i = 0; i < cdCount; i++) {
      const start = -range;
      const end = range;
      const x = Math.floor(Math.random() * (end - start + 1)) + start;
      const y = Math.floor(Math.random() * (end - start + 1)) + start;
      const cdValue = Math.floor(Math.random() * (100 - 60 + 1) + 60);
      min = min > cdValue ? cdValue : min;
      max = max < cdValue ? cdValue : max;
      const shotstart = 180;
      const shotxMax = (params.dieSizeX + params.scribeSize) * 3 - shotstart;
      const shotyMax = (params.dieSizeY + params.scribeSize) * 3 - shotstart;
      const shotx = getRangeRandom(shotstart, shotxMax);
      const shoty = getRangeRandom(shotstart, shotyMax);
      const chipstart = 60;
      const chipxMax = params.dieSizeX - chipstart;
      const chipyMax = params.dieSizeY - chipstart;
      const chipx = getRangeRandom(chipstart, chipxMax);
      const chipy = getRangeRandom(chipstart, chipyMax);

      if (Math.sqrt(x * x + y * y) < range) {
        dataList.push({
          seriesname: 'CD Group ' + (s + 1),
          id: `R${i}`,
          x: x,
          y: y,
          shotx: shotx,
          shoty: shoty,
          chipx: chipx,
          chipy: chipy,
          radius: Math.sqrt(x * x + y * y),
          cdvalue: cdValue,
        }); // Yellow
      }
    }
  }
  return { dataList, min, max };
};

const getRangeRandom = (min, max) => {
  return Math.floor(Math.random() * (max - min + 1)) + min;
};

// startColor, EndColor를 Step수 나누어서 Gradient Color List 반환한다.
export const generateGradient = (start, end, steps) => {
  // HEX를 RGB 객체로 변환하는 헬퍼 함수
  const hexToRgb = (hex) => {
    const r = parseInt(hex.substring(1, 3), 16);
    const g = parseInt(hex.substring(3, 5), 16);
    const b = parseInt(hex.substring(5, 7), 16);
    return { r, g, b };
  };

  // RGB를 HEX로 변환하는 헬퍼 함수
  const rgbToHex = (r, g, b) => {
    return '#' + [r, g, b].map((x) => Math.round(x).toString(16).padStart(2, '0')).join('');
  };

  const startRgb = hexToRgb(start);
  const endRgb = hexToRgb(end);
  const colors = [];

  for (let i = 0; i < steps; i++) {
    // 0에서 1 사이의 비율 계산
    const factor = i / (steps - 1);

    const r = startRgb.r + factor * (endRgb.r - startRgb.r);
    const g = startRgb.g + factor * (endRgb.g - startRgb.g);
    const b = startRgb.b + factor * (endRgb.b - startRgb.b);

    colors.push(rgbToHex(r, g, b));
  }

  return colors;
};
