import React from 'react';

const Copyrights = () => {
  const dependencies = [
    // --- React Core ---
    {
      name: 'React / React-DOM',
      version: '^19.2.3',
      license: 'MIT',
      copyright: 'Meta Platforms, Inc.',
    },
    { name: 'React Scripts', version: '5.0.1', license: 'MIT', copyright: 'Meta Platforms, Inc.' },
    { name: 'Web Vitals', version: '^2.1.4', license: 'Apache-2.0', copyright: 'Google LLC' },

    // --- Visualization & Charts ---
    {
      name: 'Apache ECharts',
      version: '^6.0.0',
      license: 'Apache-2.0',
      copyright: 'Apache Software Foundation',
    },
    { name: 'ECharts for React', version: '^3.0.6', license: 'MIT', copyright: 'hustcc' },
    {
      name: 'ECharts Stat',
      version: '^1.2.0',
      license: 'Apache-2.0',
      copyright: 'Apache Software Foundation',
    },
    { name: 'Chart.js', version: '^4.5.1', license: 'MIT', copyright: 'Chart.js contributors' },
    { name: 'React Chartjs 2', version: '^5.3.1', license: 'MIT', copyright: 'Jeremy Kistner' },
    { name: 'Recharts', version: '^3.6.0', license: 'MIT', copyright: 'Recharts Group' },

    // --- Table & Data Handling ---
    {
      name: 'TanStack Table (React Table)',
      version: '^8.21.3',
      license: 'MIT',
      copyright: 'Kevin Van Zonneveld',
    },
    { name: 'Axios', version: '^1.13.2', license: 'MIT', copyright: 'Matt Zabriskie' },
    { name: 'ExcelJS', version: '^4.4.0', license: 'MIT', copyright: 'Guyon Roche' },
    { name: 'XLSX (SheetJS)', version: '^0.18.5', license: 'Apache-2.0', copyright: 'SheetJS LLC' },
    { name: 'File-saver', version: '^2.0.5', license: 'MIT', copyright: 'Eli Grey' },
    { name: 'html2canvas', version: '^1.4.1', license: 'MIT', copyright: 'Niklas von Hertzen' },

    // --- UI Components ---
    { name: 'React Datepicker', version: '^9.1.0', license: 'MIT', copyright: 'HackerOne' },

    // --- Testing Libraries ---
    {
      name: '@testing-library/dom',
      version: '^10.4.1',
      license: 'MIT',
      copyright: 'Testing Library contributors',
    },
    {
      name: '@testing-library/jest-dom',
      version: '^6.9.1',
      license: 'MIT',
      copyright: 'Testing Library contributors',
    },
    {
      name: '@testing-library/react',
      version: '^16.3.1',
      license: 'MIT',
      copyright: 'Testing Library contributors',
    },
    {
      name: '@testing-library/user-event',
      version: '^13.5.0',
      license: 'MIT',
      copyright: 'Testing Library contributors',
    },
  ];

  return (
    <div style={containerStyle}>
      <div className="Scroll-Area" style={scrollAreaStyle}>
        <div style={contentCard}>
          <h1 style={titleStyle}>Open Source Licenses</h1>
          <p style={descriptionStyle}>
            본 소프트웨어는 아래의 오픈 소스 라이브러리를 사용하며, 각 라이브러리의 저작권 및
            라이선스 규정을 준수합니다.
          </p>

          <hr style={dividerStyle} />

          <div style={listContainer}>
            <table style={tableStyle}>
              <thead>
                <tr style={theadStyle}>
                  <th style={thStyle}>Library</th>
                  <th style={thStyle}>Version</th>
                  <th style={thStyle}>License</th>
                  <th style={thStyle}>Copyright</th>
                </tr>
              </thead>
              <tbody>
                {dependencies.map((lib, index) => (
                  <tr key={index} style={rowStyle}>
                    <td style={tdNameStyle}>{lib.name}</td>
                    <td style={tdStyle}>{lib.version}</td>
                    <td style={tdLicenseStyle}>
                      <span
                        style={{
                          ...badgeStyle,
                          backgroundColor: lib.license === 'Apache-2.0' ? '#e53e3e' : '#3182ce',
                        }}
                      >
                        {lib.license}
                      </span>
                    </td>
                    <td style={tdStyle}>{lib.copyright}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <section style={noticeSection}>
            <h2 style={subTitleStyle}>Legal Notice</h2>
            <div style={noticeBox}>
              <p>
                The above open-source libraries are subject to their respective licenses. The MIT
                License and Apache License 2.0 are used for the majority of these dependencies. In
                accordance with these licenses, the copyright notices and permission notices shall
                be included in all copies or substantial portions of the Software.
              </p>
              <p style={{ marginTop: '10px' }}>
                &copy; 2026 <strong>DEVICE SOLUTION</strong>. All rights reserved.
              </p>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

// --- Styles (기존과 동일하되 스크롤바 최적화 유지) ---
const containerStyle = {
  display: 'flex',
  flexDirection: 'column',
  height: 'calc(100vh - 76px)', // 부모 높이 고정
  padding: '0 15px',
  fontFamily: 'Arial',
  boxSizing: 'border-box',
  overflow: 'hidden', // 전체 브라우저 스크롤 방지
};

const scrollAreaStyle = {
  flex: 1, // 남은 전체 공간 차지
  overflowY: 'auto', // 내용이 많아지면 스크롤 생성
  marginTop: '10px',
  paddingBottom: '20px', // 하단 여백 확보
  display: 'flex', // 자식인 contentCard의 정렬을 위해 flex 사용
  flexDirection: 'column',
  alignItems: 'center', // 카드 중앙 정렬 (선택 사항)
};

const contentCard = {
  width: '100%',
  maxWidth: '1200px', // 너무 넓어지지 않게 제한 (선택 사항)
  backgroundColor: '#1e293b',
  padding: '40px',
  borderRadius: '12px',
  border: '1px solid #334155',
  boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.3)',
  flexShrink: 0, // 내용이 작아도 카드가 찌그러지지 않게 설정
};
const titleStyle = { color: '#63b3ed', fontSize: '28px', marginBottom: '10px', fontWeight: '800' };
const descriptionStyle = {
  color: '#94a3b8',
  fontSize: '14px',
  lineHeight: '1.6',
  marginBottom: '30px',
};
const dividerStyle = { border: 'none', borderBottom: '1px solid #334155', marginBottom: '30px' };
const listContainer = {
  marginTop: '20px',
  marginBottom: '40px',
  maxHeight: '500px',
  overflowY: 'auto',
  paddingRight: '10px',
  borderRadius: '8px',
};
const tableStyle = { width: '100%', borderCollapse: 'collapse', fontSize: '13px' };
const theadStyle = {
  borderBottom: '2px solid #334155',
  textAlign: 'left',
  position: 'sticky',
  top: 0,
  backgroundColor: '#1e293b',
  zIndex: 1,
};
const thStyle = { padding: '12px', color: '#cbd5e1', fontWeight: '600' };
const rowStyle = { borderBottom: '1px solid #334155' };
const tdStyle = { padding: '12px', color: '#94a3b8' };
const tdNameStyle = { padding: '12px', color: '#f8fafc', fontWeight: '500' };
const tdLicenseStyle = { padding: '12px' };
const badgeStyle = {
  color: '#fff',
  padding: '2px 8px',
  borderRadius: '4px',
  fontSize: '11px',
  fontWeight: 'bold',
};
const noticeSection = { marginTop: '40px' };
const subTitleStyle = { color: '#cbd5e1', fontSize: '18px', marginBottom: '15px' };
const noticeBox = {
  padding: '20px',
  backgroundColor: '#0f172a',
  borderRadius: '8px',
  border: '1px solid #334155',
  color: '#64748b',
  fontSize: '12px',
  lineHeight: '1.8',
};

export default Copyrights;
