export const generateDatas = (selectedParams) => {
  const newData = [];
  const excludeKeys = ['y2item', 'chartEngine', 'chartType', 'date'];

  // 1. 설비(equip)별 데이터 분포 정의 (평균값, 표준편차 대용)
  const equipSpecs = {
    'EQP-01': { base: 20, range: 15 }, // 낮은 값 분포
    'EQP-02': { base: 45, range: 10 }, // 중간 값 분포
    'EQP-03': { base: 55, range: 30 }, // 높은 값, 정밀한 분포
    'EQP-04': { base: 40, range: 2 }, // 매우 낮은 값
    'EQP-05': { base: 50, range: 20 }, // 넓은 변동폭
    Unknown: { base: 55, range: 10 },
  };

  const targetKeys = Object.keys(selectedParams).filter(
    (key) =>
      !excludeKeys.includes(key) &&
      Array.isArray(selectedParams[key]) &&
      selectedParams[key].length > 0,
  );

  const getCombinations = (keys, params) => {
    return keys.reduce(
      (acc, key) => {
        const combinations = [];
        acc.forEach((prevCombination) => {
          params[key].forEach((value) => {
            // step 등 객체 형태인 경우 대비하여 값 추출
            const val = typeof value === 'object' ? value[key] : value;
            combinations.push({ ...prevCombination, [key]: val });
          });
        });
        return combinations;
      },
      [{}],
    );
  };

  const allCombinations = getCombinations(targetKeys, selectedParams);

  let globalStartTime = new Date();
  globalStartTime.setHours(globalStartTime.getHours() - 24);

  const lotCount = 2;
  const waferCount = 5;

  allCombinations.forEach((combination, combIdx) => {
    let combinationStartTime = new Date(globalStartTime.getTime() + combIdx * 3600000);

    // 현재 조합의 설비(equip) 확인
    const currentEquip = combination.equip || 'Unknown';
    const spec = equipSpecs[currentEquip] || equipSpecs['Unknown'];
    const now = new Date();
    const tenDaysAgo = 10 * 24 * 60 * 60 * 1000;
    const threeDaysInMs =
      (Math.random() * (3 - 1) + 1) * (Math.random() * (24 - 1) + 1) * 60 * 60 * 1000; // 3일(ms)

    for (let l = 0; l < lotCount; l++) {
      const lotId = `LOT-${String(l + 1).padStart(3, '0')}`;

      for (let w = 0; w < waferCount; w++) {
        const waferId = `W-${String(w + 1).padStart(2, '0')}`;
        const outTimeDate = new Date(now.getTime() - Math.random() * tenDaysAgo);
        const inTimeDate = new Date(outTimeDate.getTime() - threeDaysInMs);

        // --- 설비별 차별화된 value 생성 로직 ---
        // spec.base를 중심으로 spec.range 범위 내에서 랜덤값 생성
        const val = spec.base + (Math.random() - 0.5) * spec.range;

        const row = {
          ...combination,
          lot_id: lotId,
          wafer_id: waferId,
          value: parseFloat(val.toFixed(2)),
          tkin_time: new Date(inTimeDate).toISOString().replace('T', ' ').split('.')[0],
          tkout_time: new Date(outTimeDate).toISOString().replace('T', ' ').split('.')[0],
        };

        newData.push(row);
      }
    }
  });

  return newData;
};
