import React, { useState, useRef, useEffect } from 'react';

const CheckboxCombo = ({
  label = '선택하세요',
  options = [],
  selectedValues = [],
  onSelectChange,
  isShowButton = false,
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [dropUp, setDropUp] = useState(false); // 위로 띄울지 여부 상태
  const containerRef = useRef(null);

  // 드롭다운 열릴 때 위치 계산
  useEffect(() => {
    if (isOpen && containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const viewportHeight = window.innerHeight;
      const dropdownMaxHeight = 250; // 버튼 영역 + listAreaStyle(200px) 추정치

      // 아래쪽 공간이 부족하고, 위쪽 공간이 아래쪽보다 많을 때 위로 띄움
      if (viewportHeight - rect.bottom < dropdownMaxHeight && rect.top > dropdownMaxHeight) {
        setDropUp(true);
      } else {
        setDropUp(false);
      }
    }
  }, [isOpen]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const toggleOption = (id) => {
    const isSelected = selectedValues.includes(id);
    const updatedSelected = isSelected
      ? selectedValues.filter((item) => item !== id)
      : [...selectedValues, id];
    onSelectChange(updatedSelected);
  };

  const handleBulkSelect = (type) => {
    const updatedSelected = type === 'ALL' ? options.map((o) => o.id) : [];
    onSelectChange(updatedSelected);
  };

  return (
    <div ref={containerRef} style={comboContainerStyle}>
      <div style={selectBoxStyle} onClick={() => setIsOpen(!isOpen)}>
        <span style={textStyle}>
          {selectedValues.length > 0 ? `${selectedValues.length}개 선택됨` : label}
        </span>
        <span style={arrowStyle}>{isOpen ? '▲' : '▼'}</span>
      </div>

      {isOpen && (
        <div
          style={{
            ...dropdownStyle,
            // dropUp 상태에 따라 위치 동적 변경
            top: dropUp ? 'auto' : '100%',
            bottom: dropUp ? '100%' : 'auto',
            marginBottom: dropUp ? '4px' : '0',
            marginTop: dropUp ? '0' : '4px',
            // 위로 열릴 때 그림자 방향 수정
            boxShadow: dropUp ? '0 -4px 12px rgba(0,0,0,0.1)' : '0 4px 12px rgba(0,0,0,0.1)',
          }}
        >
          {isShowButton && (
            <div style={actionHeaderStyle}>
              <button style={actionBtnStyle} onClick={() => handleBulkSelect('ALL')}>
                전체선택
              </button>
              <button style={actionBtnStyle} onClick={() => handleBulkSelect('NONE')}>
                전체해제
              </button>
            </div>
          )}
          <div style={listAreaStyle}>
            {options.length > 0 ? (
              options.map((option) => {
                // option이 객체면 option.id, 문자열이면 값 자체를 ID로 사용
                const id = typeof option === 'object' ? option.id : option;
                const name = typeof option === 'object' ? option.name : option;
                const isChecked = selectedValues.includes(id);

                return (
                  <label
                    key={id}
                    style={{ ...itemStyle, backgroundColor: isChecked ? '#f0f7ff' : 'transparent' }}
                  >
                    <input
                      type="checkbox"
                      checked={isChecked}
                      onChange={() => toggleOption(id)} // ID를 넘김
                      style={checkboxStyle}
                    />
                    <span style={{ color: isChecked ? '#228be6' : '#333' }}>{name}</span>
                  </label>
                );
              })
            ) : (
              <div style={noDataStyle}>데이터가 없습니다.</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// --- 스타일 (변경된 부분 위주) ---
const comboContainerStyle = { position: 'relative', minWidth: '100px', fontSize: '11px' };
const selectBoxStyle = {
  padding: '3px 10px',
  border: '1px solid #ccc',
  borderRadius: '4px',
  cursor: 'pointer',
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  backgroundColor: '#fff',
};
const textStyle = { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' };
const arrowStyle = { fontSize: '10px', color: '#888' };

const dropdownStyle = {
  position: 'absolute',
  left: 0,
  right: 0,
  zIndex: 100,
  border: '1px solid #ddd',
  backgroundColor: '#fff',
  borderRadius: '4px',
};

const actionHeaderStyle = {
  padding: '6px',
  borderBottom: '1px solid #eee',
  display: 'flex',
  gap: '4px',
  backgroundColor: '#f9fafb',
  justifyContent: 'flex-end',
};
const actionBtnStyle = {
  padding: '2px 6px',
  fontSize: '11px',
  cursor: 'pointer',
  backgroundColor: '#fff',
  border: '1px solid #d1d5db',
  borderRadius: '3px',
};
const listAreaStyle = { maxHeight: '200px', overflowY: 'auto' };
const itemStyle = {
  display: 'flex',
  alignItems: 'center',
  padding: '2px 10px',
  cursor: 'pointer',
  gap: '8px',
  fontSize: '12px',
};
const checkboxStyle = { cursor: 'pointer', width: '14px', height: '14px' };
const noDataStyle = { padding: '15px', textAlign: 'center', color: '#999', fontSize: '12px' };

export default CheckboxCombo;
