import React, { useState } from 'react';

// 개별 노드 컴포넌트
const TreeNode = ({ node, parentPath = '', onSelect }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const hasChildren = node.children && node.children.length > 0;
  const currentFullPath = parentPath ? `${parentPath}/${node.name}` : node.name;

  const handleNodeClick = (e) => {
    e.stopPropagation();
    if (hasChildren) setIsExpanded(!isExpanded);

    // 클릭 시 데이터를 부모로 전달
    onSelect({
      id: node.id,
      folder: parentPath,
      groupname: node.name,
      fullPath: currentFullPath,
    });
  };

  const nodeStyle = {
    cursor: 'pointer',
    padding: '3px 6px',
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    borderRadius: '3px',
    fontSize: '13px',
    transition: 'all 0.1s ease',
    userSelect: 'none',
    color: '#333',
  };

  return (
    <div style={{ paddingLeft: '14px', marginTop: '1px' }}>
      <div
        className="tree-node"
        onClick={handleNodeClick}
        style={nodeStyle}
        onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#f0f0f0')}
        onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'transparent')}
      >
        <span style={{ fontSize: '10px', width: '12px', display: 'inline-block', color: '#999' }}>
          {hasChildren ? (isExpanded ? '▼' : '▶') : ''}
        </span>
        <span style={{ fontSize: '14px' }}>{hasChildren ? (isExpanded ? '📂' : '📁') : '📄'}</span>
        <span style={{ fontWeight: hasChildren ? '500' : '400', letterSpacing: '-0.2px' }}>
          {node.name}
        </span>
      </div>

      {hasChildren && isExpanded && (
        <div style={{ borderLeft: '1px solid #e5e5e5', marginLeft: '6px' }}>
          {node.children.map((child, index) => (
            <TreeNode
              key={child.id || `${currentFullPath}-${index}`}
              node={child}
              parentPath={currentFullPath}
              onSelect={onSelect}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// 트리 변환 로직
const transformToTree = (paths) => {
  if (!paths) return [];
  const root = [];
  paths.forEach((path) => {
    const parts = path.folder.split('/');
    let currentLevel = root;

    parts.forEach((part) => {
      let existingNode = currentLevel.find((node) => node.name === part);
      if (!existingNode) {
        existingNode = { id: null, name: part, children: [] };
        currentLevel.push(existingNode);
      }
      currentLevel = existingNode.children;
    });

    let existingNode = currentLevel.find((node) => node.name === path.groupname);
    if (!existingNode) {
      existingNode = { id: path.id, name: path.groupname, children: [] };
      currentLevel.push(existingNode);
    }
  });
  return root;
};

// 메인 트리 컴포넌트
// indata: 트리 구성 데이터, selectedData: 선택된 값을 받을 콜백 함수
const TreeList = ({ indata, title = 'Work List Folder', selectedData }) => {
  // 만약 indata가 전달되지 않았을 경우를 대비한 기본 데이터
  const defaultData = [
    { id: '1', folder: 'root/testGroup/test1', groupname: 'testGroup1' },
    { id: '2', folder: 'root/testGroup/test1', groupname: 'testGroup2' },
    { id: '3', folder: 'root/testGroup/test2', groupname: 'testGroup3' },
    { id: '4', folder: 'root/testGroup/test2', groupname: 'testGroup4' },
    { id: '5', folder: 'root/testGroup', groupname: 'testGroup5' },
    { id: '1', folder: 'root/testGroup2/test1', groupname: 'testGroup21' },
    { id: '2', folder: 'root/testGroup2/test1', groupname: 'testGroup22' },
    { id: '3', folder: 'root/testGroup2/test2', groupname: 'testGroup23' },
    { id: '4', folder: 'root/testGroup2/test2', groupname: 'testGroup24' },
    { id: '5', folder: 'root/testGroup2', groupname: 'testGroup25' },
  ];

  const categoryData = transformToTree(indata || defaultData);

  // 내부 핸들러에서 외부 props로 받은 selectedData를 실행
  const handleSelectNode = (data) => {
    //console.log(`id: ${data.id}, folder: ${data.folder}, groupname: ${data.groupname}`);
    if (selectedData) {
      selectedData(data); // 부모 컴포넌트로 데이터 반환
    }
  };

  return (
    <div style={{ paddingRight: '10px', backgroundColor: '#fff' }}>
      <h4
        style={{
          margin: '0 0 2px 0',
          fontSize: '13px',
          color: '#222',
          paddingBottom: '4px',
          borderBottom: '2px solid #3182ce',
        }}
      >
        {title}
      </h4>
      <div
        style={{
          border: '1px solid #eaeaea',
          padding: '5px 2px',
          borderRadius: '6px',
          Width: '100%',
          backgroundColor: '#fafafa',
        }}
      >
        {categoryData.map((item, index) => (
          <TreeNode key={item.id || index} node={item} onSelect={handleSelectNode} />
        ))}
      </div>
    </div>
  );
};

export default TreeList;
