import React, { useState, useEffect } from 'react';
import DateSelector from './DateSelector';
import CustomAlert from '../utils/CustomAlert';

/**
 * LineSelector Component
 * * @param {string} label - 카테고리 타이틀 (예: "Line", "Equipment")
 * @param {string} category - 부모로부터 전달받은 상태 식별 키
 * @param {string} filterValue - 검색창 입력값
 * @param {string} lableWidth - 라벨 영역 너비 (기본값: '50px')
 * @param {function} onFilterChange - 필터 입력 시 호출되는 함수
 * @param {function} onFetch - 데이터 조회 버튼 클릭/Enter 시 호출되는 함수
 * @param {Array} options - 리스트에 렌더링될 데이터 배열
 * @param {Array} selectedValues - 현재 선택된 항목 값 배열
 * @param {function} onSelectChange - 항목 선택 변경 시 호출되는 핸들러
 * @param {function} onDateChange - 날짜 변경 시 호출되는 핸들러 (DateSelector 전달용)
 * @param {boolean} isMulti - 다중 선택 모드 여부
 */
const LineSelector = ({
  label,
  category,
  filterValue,
  labelWidth = '50px',
  onFilterChange,
  onFetch,
  options = [],
  selectedValues = [],
  onSelectChange,
  onDateChange,
  datePickerHeight = '18px',
  dateFontSize = '9px',
  isMulti = true,
  /**
   * [추가] returnType 설정
   * 'diff': 기존 방식 (-7, 0)
   * 'date': 날짜만 (2026-01-31)
   * 'datetime': 시분초 포함 (2026-01-31 00:00:00 / 23:59:59)
   */
  returnType = 'diff',
}) => {
  // 드래그 상태 관리: 마우스를 누른 채 이동하는지 추적
  const [isDragging, setIsDragging] = useState(false);
  const [alertConfig, setAlertConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
  });

  // 알림창을 여는 통합 함수
  const showAlert = (type) => {
    const configs = {
      filterError: {
        title: '필터 오류',
        message: '보안을 위해 특수문자(<, >, \', ", ;, -)는 입력할 수 없습니다.',
      },
      filterCount: {
        title: '필터 개수 제한',
        message: '필터는 최대 3개까지만 입력할 수 있습니다.',
      },
      selectionRequired: {
        title: '선택 필요',
        message: '상위 Selector를 먼저 선택해야 합니다.',
      },
    };

    setAlertConfig({
      isOpen: true,
      ...configs[type], // 선택한 타입의 데이터를 복사
    });
  };

  const closeAlert = () => setAlertConfig({ ...alertConfig, isOpen: false });

  // 전역 마우스 업 이벤트 처리: 리스트 밖에서 마우스를 떼도 드래그가 종료되도록 보장
  useEffect(() => {
    const handleMouseUpGlobal = () => setIsDragging(false);
    window.addEventListener('mouseup', handleMouseUpGlobal);
    return () => window.removeEventListener('mouseup', handleMouseUpGlobal);
  }, []);

  /**
   * [Security] 입력 필터링
   * SQL Injection 및 기본적인 스크립트 공격 방지를 위해 특수문자 제한
   */
  const handleInputChange = (e) => {
    const value = e.target.value;
    const securityPattern = /[<>'"\\;\-]/g;

    if (securityPattern.test(value)) {
      showAlert('filterError');
      onFilterChange(category, '');
      return;
    }
    const filters = value
      .trim()
      .split(',')
      .map((v) => v.trim().toLowerCase());
    if (filters.length === 1 && filters[0] === '') {
      onFilterChange(category, []);
      return;
    }
    if (filters.length > 3) {
      showAlert('filterCount');
      return;
    }
    onFilterChange(category, filters);
  };

  /**
   * [Interaction] Enter 키 핸들러
   */
  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      onFetch(category);
    }
  };

  /**
   * [Logic] 항목 선택 업데이트
   * @param {any} item - 대상 데이터
   * @param {boolean} isAdding - 드래그 중인지 여부 (추가 전용 모드)
   */
  const updateSelection = (item, isAdding) => {
    // 단일 선택 모드 로직
    if (!isMulti) {
      const newSelected = selectedValues.includes(item) ? [] : [item];
      triggerChange(newSelected);
      return;
    }

    let newSelected;
    if (isAdding) {
      // 드래그 중인 경우: 중복 방지하며 추가만 수행
      if (!selectedValues.includes(item)) {
        newSelected = [...selectedValues, item];
      } else {
        return;
      }
    } else {
      // 클릭 시: 선택되어 있으면 제거, 아니면 추가 (토글)
      newSelected = selectedValues.includes(item)
        ? selectedValues.filter((v) => v !== item)
        : [...selectedValues, item];
    }
    triggerChange(newSelected);
  };

  /**
   * [Emitter] 부모 상태 업데이트 트리거
   */
  const triggerChange = (newSelected) => {
    onSelectChange({
      target: {
        name: category,
        options: options.map((opt) => ({
          value: opt,
          selected: newSelected.includes(opt),
        })),
      },
    });
  };

  // 마우스 클릭 시점
  const handleMouseDown = (item) => {
    if (isMulti) setIsDragging(true);
    updateSelection(item, false);
  };

  // 마우스 드래그 진입 시점
  const handleMouseEnter = (item) => {
    if (isDragging && isMulti) {
      updateSelection(item, true);
    }
  };

  return (
    <div style={{ ...containerStyle, height: '100%' }}>
      {/* 1. 상단: 타이틀 및 필터 서치바 영역 */}
      <div style={headerStyle}>
        <label style={{ ...labelStyle, width: labelWidth }}>{label}</label>
        <div style={inputGroupStyle}>
          <input
            type="text"
            style={inputStyle}
            placeholder="fiter 구분자 콤마만 허용"
            value={filterValue}
            onChange={handleInputChange}
            onKeyDown={handleKeyDown}
          />
          <button style={fetchBtnStyle} onClick={() => onFetch(category)}>
            🔍
          </button>
        </div>
      </div>

      {/* 2. 중앙: 커스텀 리스트 렌더링 영역 */}
      <div style={{ ...listContainerStyle, flex: 1, minHeight: 0 }}>
        <div style={customListStyle} onMouseLeave={() => setIsDragging(false)}>
          {options && options.length > 0 ? (
            options.map((item) => {
              const isSelected = selectedValues.includes(item);
              return (
                <div
                  key={item}
                  onMouseDown={() => handleMouseDown(item)}
                  onMouseEnter={() => handleMouseEnter(item)}
                  style={{
                    ...optionItemStyle,
                    backgroundColor: isSelected ? '#e7f5ff' : 'transparent',
                    color: isSelected ? '#228be6' : '#333',
                    fontWeight: isSelected ? '700' : '400',
                    userSelect: 'none',
                  }}
                >
                  {item}
                </div>
              );
            })
          ) : (
            <div style={noDataStyle}>No Data</div>
          )}
        </div>
      </div>

      {/* 3. 하단 섹션: 날짜 선택기(DateSelector) + 선택 상태 정보바 */}
      <div style={footerContainerStyle}>
        <div style={dateSectionStyle}>
          <DateSelector
            onDateChange={onDateChange}
            pickerHeight={datePickerHeight}
            fontSize={dateFontSize}
            pickerMinWidth="121px"
            returnType={returnType}
          />
        </div>
        <div style={footerStatusStyle}>
          <span style={countBadgeStyle}>
            {Array.isArray(selectedValues) ? selectedValues.length : 0}
          </span>
          <span style={{ color: '#999' }}>Sel</span>
        </div>
      </div>
      {alertConfig.isOpen && (
        <CustomAlert
          title={alertConfig.title}
          message={alertConfig.message}
          onConfirm={closeAlert}
          onCancel={closeAlert}
        />
      )}
    </div>
  );
};

// --- 스타일 가이드 (Compact 디자인 최적화) ---

const containerStyle = {
  flex: 1,
  backgroundColor: '#ffffff',
  borderRadius: '4px',
  padding: '6px 8px',
  border: '1px solid #e1e4e8',
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
};

const headerStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '4px',
};

const labelStyle = {
  fontSize: '10px',
  fontWeight: '700',
  color: '#44546a',
  textTransform: 'uppercase',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
};

const inputGroupStyle = {
  display: 'flex',
  flex: 1,
  height: '20px',
  borderRadius: '3px',
  overflow: 'hidden',
  border: '1px solid #d1d5db',
};

const inputStyle = {
  flex: 1,
  border: 'none',
  padding: '0 4px',
  fontSize: '10px',
  outline: 'none',
  backgroundColor: '#f9fafb',
};

const fetchBtnStyle = {
  width: '24px',
  border: 'none',
  borderLeft: '1px solid #d1d5db',
  backgroundColor: '#fff',
  fontSize: '9px',
  fontWeight: '700',
  color: '#007bff',
  cursor: 'pointer',
};

const customListStyle = {
  position: 'absolute', // [중요] 부모(listContainerStyle)가 확보한 공간에 박제
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  border: '1px solid #e1e4e8',
  borderRadius: '3px',
  overflowY: 'auto', // 넘치는 데이터는 스크롤 처리
  backgroundColor: '#fff',
};

const optionItemStyle = {
  padding: '2px 6px',
  fontSize: '10px',
  cursor: 'pointer',
  borderBottom: '1px solid #f8fafc',
  userSelect: 'none',
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
};

const listContainerStyle = {
  flex: 1, // 상단과 하단을 제외한 모든 공간 차지
  position: 'relative', // [중요] 자식(customListStyle)의 기준점
  minHeight: 0, // [중요] 콘텐츠 양에 따라 늘어나는 기본 속성 차단
  marginTop: '1px',
  marginBottom: '1px',
};

const noDataStyle = {
  textAlign: 'center',
  paddingTop: '10px',
  color: '#ccc',
  fontSize: '10px',
};

const footerContainerStyle = {
  display: 'flex',
  flexDirection: 'column',
  gap: '1px',
  paddingTop: '1px',
  borderTop: '1px dashed #f0f0f0',
};

const dateSectionStyle = {
  display: 'flex',
  justifyContent: 'center',
  backgroundColor: '#f8fafc',
  padding: '1px',
  borderRadius: '3px',
};

const footerStatusStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '3px',
  fontSize: '9px',
  justifyContent: 'flex-end',
};

const countBadgeStyle = {
  backgroundColor: '#e7f5ff',
  color: '#228be6',
  padding: '0px 4px',
  borderRadius: '6px',
  fontWeight: '800',
  fontSize: '9px',
};

export default LineSelector;
